update proj_project
project_code = #{projectCode}, project_name = #{projectName}, engineering_project = #{engineeringProject}, project_category_id = #{projectCategoryId}, client_unit = #{clientUnit}, contact_name = #{contactName}, contact_phone = #{contactPhone}, project_location = #{projectLocation}, contract_id = #{contractId}, status = #{status}, assign_date = #{assignDate}, duration_require = #{durationRequire}, total_duration = #{totalDuration}, extra_data = #{extraData}::jsonb, related_project_id = #{relatedProjectId}, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where id = #{id}

update proj_project set status = #{status},
    close_time = case when #{status} = 'closed' then now() else close_time end,
    update_time = now() where id = #{id}
